('Aristoteles', 'Zweifel ist der Beginn der Weisheit.', 'Zweifel,Weisheit'),
('Aristoteles', 'Der Weise redet nicht über Dinge, die er nicht versteht.', 'Weisheit,Ehrlichkeit'),
('Aristoteles', 'Es gibt nur einen Weg, um Kritik zu vermeiden: Nichts tun, nichts sagen, nichts sein.', 'Kritik,Handeln'),
('Aristoteles', 'Erziehung des Geistes ohne Erziehung des Herzens ist keine Erziehung.', 'Bildung,Ethik'),
('Aristoteles', 'Armut ist die Mutter von Verbrechen und Revolution.', 'Armut,Staat,Gesellschaft'),
('Aristoteles', 'Witz ist gebildete Unverschämtheit.', 'Humor,Intelligenz');

-- ERGÄNZUNGS-BLOCK B: Gandhi, Einstein, Mark Aurel & Oscar Wilde (Vervollständigung)
INSERT INTO `sayings` (`author`, `content`, `tags`) VALUES
-- MAHATMA GANDHI
('Mahatma Gandhi', 'Zuerst ignorieren sie dich, dann lachen sie über dich, dann bekämpfen sie dich und dann gewinnst du.', 'Widerstand,Erfolg,Politik'),
('Mahatma Gandhi', 'Auge um Auge macht die ganze Welt blind.', 'Frieden,Rache,Ethik'),
('Mahatma Gandhi', 'Stärke wächst nicht aus körperlicher Kraft – vielmehr aus unbeugsamen Willen.', 'Stärke,Wille,Charakter'),
('Mahatma Gandhi', 'Wo Liebe ist, da ist auch Leben.', 'Liebe,Leben'),
('Mahatma Gandhi', 'Die Zukunft hängt davon ab, was wir heute tun.', 'Zukunft,Handeln,Verantwortung'),
('Mahatma Gandhi', 'Es gibt keinen Weg zum Frieden, denn Frieden ist der Weg.', 'Frieden,Ethik'),
('Mahatma Gandhi', 'Meine Religion ist sehr einfach. Meine Religion ist Güte.', 'Religion,Güte,Ethik'),
('Mahatma Gandhi', 'Das Recht zu leben ist ein Privileg, das mit Verpflichtungen einhergeht.', 'Recht,Pflicht,Leben'),
('Mahatma Gandhi', 'Ein Nein aus tiefster Überzeugung ist besser als ein Ja, um zu gefallen.', 'Ehrlichkeit,Mut,Charakter'),
('Mahatma Gandhi', 'Glück ist, wenn das, was du denkst, was du sagst und was du tust, in Harmonie sind.', 'Glück,Harmonie,Integrität'),
('Mahatma Gandhi', 'Die Welt hat genug für jedermanns Bedürfnisse, aber nicht für jedermanns Gier.', 'Gier,Wirtschaft,Natur'),
('Mahatma Gandhi', 'Ein Gramm Praxis ist mehr wert als eine Tonne Theorie.', 'Handeln,Erfahrung'),
('Mahatma Gandhi', 'Man kann nicht die Hand schütteln mit einer geballten Faust.', 'Frieden,Diplomatie'),
('Mahatma Gandhi', 'Hass ist eine Sache, die man am besten denjenigen überlässt, die kein Herz haben.', 'Hass,Ethik'),
('Mahatma Gandhi', 'Verzeihen ist eine Eigenschaft der Starken. Die Schwachen können niemals verzeihen.', 'Vergebung,Stärke'),
('Mahatma Gandhi', 'Sich selbst zu finden bedeutet, sich im Dienst an anderen zu verlieren.', 'Sinn,Dienst,Selbstfindung'),
('Mahatma Gandhi', 'Ein Fehler wird erst dann zum Fehler, wenn man ihn nicht korrigiert.', 'Fehler,Lernen'),
('Mahatma Gandhi', 'Freiheit ist nichts wert, wenn sie nicht die Freiheit einschließt, zu irren.', 'Freiheit,Fehler'),

-- ALBERT EINSTEIN
('Albert Einstein', 'Zwei Dinge sind unendlich, das Universum und die menschliche Dummheit, aber bei dem Universum bin ich mir noch nicht ganz sicher.', 'Dummheit,Universum,Humor'),
('Albert Einstein', 'Logik bringt dich von A nach B. Phantasie überall hin.', 'Phantasie,Logik,Geist'),
('Albert Einstein', 'Wer noch nie einen Fehler gemacht hat, hat noch nie etwas Neues ausprobiert.', 'Fehler,Innovation,Lernen'),
('Albert Einstein', 'Mache die Dinge so einfach wie möglich, aber nicht einfacher.', 'Einfachheit,Wissenschaft'),
('Albert Einstein', 'Probleme kann man niemals mit derselben Denkweise lösen, durch die sie entstanden sind.', 'Problemlösung,Denken,Wandel'),
('Albert Einstein', 'Genie ist 1% Inspiration und 99% Transpiration.', 'Erfolg,Arbeit,Genie'),
('Albert Einstein', 'Der Horizont vieler Menschen ist ein Kreis mit dem Radius Null – und das nennen sie ihren Standpunkt.', 'Perspektive,Intelligenz,Kritik'),
('Albert Einstein', 'Gott würfelt nicht.', 'Wissenschaft,Glaube,Ordnung'),
('Albert Einstein', 'Inmitten von Schwierigkeiten liegen Möglichkeiten.', 'Resilienz,Chancen'),
('Albert Einstein', 'Die reinste Form des Wahnsinns ist es, alles beim Alten zu lassen und gleichzeitig zu hoffen, dass sich etwas ändert.', 'Wahnsinn,Wandel,Gewohnheit'),
('Albert Einstein', 'Wissenschaft ohne Religion ist lahm, Religion ohne Wissenschaft ist blind.', 'Wissenschaft,Religion'),
('Albert Einstein', 'Jeder ist ein Genie! Aber wenn du einen Fisch danach beurteilst, ob er auf einen Baum klettern kann, wird er sein ganzes Leben glauben, dass er dumm ist.', 'Bildung,Individuum,Potenzial'),
('Albert Einstein', 'Wichtig ist, dass man nie aufhört zu fragen.', 'Lernen,Neugier'),
('Albert Einstein', 'Wer sich nicht mehr wundern kann, ist seelisch bereits tot.', 'Staunen,Geist'),

-- MARK AUREL
('Mark Aurel', 'Du hast Macht über deinen Verstand – nicht über äußere Ereignisse. Erkenne dies, und du wirst Stärke finden.', 'Stoizismus,Macht,Geist'),
('Mark Aurel', 'Alles, was wir hören, ist eine Meinung, kein Fakt. Alles, was wir sehen, ist eine Perspektive, nicht die Wahrheit.', 'Wahrheit,Perspektive,Verstand'),
('Mark Aurel', 'Verliere keine Zeit mehr damit, darüber zu streiten, was ein guter Mann sein sollte. Sei einer.', 'Handeln,Charakter,Ethik'),
('Mark Aurel', 'Die beste Rache ist, nicht so zu sein wie dein Feind.', 'Rache,Charakter,Ethik'),
('Mark Aurel', 'Was nicht gut ist für den Bienenstock, ist auch nicht gut für die Biene.', 'Gemeinschaft,Individuum,Natur'),
('Mark Aurel', 'Wer mit sich selbst eins ist, ist mit dem Universum eins.', 'Harmonie,Spiritualität'),
('Mark Aurel', 'Der Tod lächelt uns alle an. Das Einzige, was man machen kann, ist zurücklächeln.', 'Tod,Mut,Akzeptanz'),
('Mark Aurel', 'Tu alles so, als wäre es das Letzte, was du in deinem Leben tust.', 'Präsenz,Leben,Tod'),
('Mark Aurel', 'Wie viel Zeit spart derjenige, der nicht darauf schaut, was sein Nachbar sagt oder tut.', 'Zeit,Fokus,Selbstvertrauen'),
('Mark Aurel', 'Nichts passiert einem Menschen, das er nicht von Natur aus ertragen kann.', 'Resilienz,Schicksal'),
('Mark Aurel', 'Das Ziel des Lebens ist nicht, auf der Seite der Mehrheit zu stehen, sondern dem Wahnsinn zu entkommen.', 'Individuum,Demokratie,Wahrheit'),
('Mark Aurel', 'Sei wie der Fels, an dem sich die Wellen ständig brechen.', 'Stärke,Resilienz'),

-- OSCAR WILDE
('Oscar Wilde', 'Ich habe einen ganz einfachen Geschmack: Ich bin immer mit dem Besten zufrieden.', 'Genuss,Humor,Lebensstil'),
('Oscar Wilde', 'Am Ende wird alles gut. Wenn es nicht gut ist, ist es noch nicht das Ende.', 'Hoffnung,Optimismus'),
('Oscar Wilde', 'Versuchung sollte man nachgeben. Wer weiß, ob sie wiederkommt!', 'Versuchung,Genuss,Humor'),
('Oscar Wilde', 'Die einzige Art, eine Versuchung loszuwerden, ist, ihr nachzugeben.', 'Versuchung,Psychologie'),
('Oscar Wilde', 'Wir liegen alle in der Gosse, aber einige von uns betrachten die Sterne.', 'Hoffnung,Perspektive,Idealismus'),
('Oscar Wilde', 'Die meisten Menschen sind andere Menschen. Ihre Gedanken sind die Meinungen anderer.', 'Individuum,Konformität,Geist'),
('Oscar Wilde', 'Zyniker: ein Mensch, der von allem den Preis und von nichts den Wert kennt.', 'Werte,Geld,Zynismus'),
('Oscar Wilde', 'Ein Experte ist ein Mann, der hinterher genau sagen kann, warum seine Prognose nicht eingetroffen ist.', 'Wissen,Humor,Kritik'),
('Oscar Wilde', 'Mode ist eine so unerträgliche Form der Hässlichkeit, dass wir sie alle sechs Monate ändern müssen.', 'Mode,Gesellschaft,Humor'),
('Oscar Wilde', 'Kein Mensch ist reich genug, um seine eigene Vergangenheit zurückzukaufen.', 'Zeit,Vergangenheit,Geld'),
('Oscar Wilde', 'Jeder kann die Leiden eines Freundes bedauern. Es bedarf aber eines sehr edlen Charakters, um sich über die Erfolge eines Freundes zu freuen.', 'Freundschaft,Charakter,Neid'),
('Oscar Wilde', 'Egoismus besteht nicht darin, so zu leben, wie man will, sondern von anderen zu verlangen, dass sie so leben, wie man will.', 'Egoismus,Freiheit,Gesellschaft'),
('Oscar Wilde', 'Die Welt ist eine Bühne, aber das Stück ist schlecht besetzt.', 'Gesellschaft,Kritik,Humor');


-- ERGÄNZUNGS-BLOCK C: Konservative Politik & Libertäre Vertiefung
INSERT INTO `sayings` (`author`, `content`, `tags`) VALUES
-- KONSERVATIVE POLITIKER
('Konrad Adenauer', 'Ein kluger Mann macht nicht alle Fehler selber. Er gibt auch anderen eine Chance.', 'Fehler,Humor,Klugheit'),
('Ludwig Erhard', 'Ein Volk kann nicht mehr verbrauchen, als es selbst erzeugt.', 'Wirtschaft,Geld,Produktion'),
('Ludwig Erhard', 'Wettbewerb ist das beste Entmachtungsmittel.', 'Markt,Wettbewerb,Macht'),
('Franz Josef Strauß', 'Bayern ist die Vorstufe zum Paradies.', 'Heimat,Bayern,Humor'),
('Franz Josef Strauß', 'Ein Politiker muss das Herz am rechten Fleck haben, aber den Verstand im Kopf.', 'Politik,Verstand,Ethik'),
('Franz Josef Strauß', 'Wer nicht weiß, woher er kommt, weiß nicht, wohin er geht.', 'Tradition,Zukunft,Geschichte'),
('Helmut Kohl', 'Die Geschichte kennt kein Halten.', 'Geschichte,Wandel,Politik'),
('Helmut Kohl', 'Europa ist unsere Zukunft, Deutschland unsere Heimat.', 'Europa,Heimat,Politik'),
('Otto von Bismarck', 'Die erste Generation schafft Vermögen, die zweite verwaltet es, die dritte studiert Kunstgeschichte.', 'Geld,Generation,Gesellschaft'),
('Otto von Bismarck', 'Wir Deutsche fürchten Gott, aber sonst nichts in der Welt.', 'Mut,Glaube,Nation'),
('Otto von Bismarck', 'Diplomatie ist die Kunst, den anderen daran zu erinnern, was er eigentlich wollte.', 'Diplomatie,Politik,Strategie'),
('Richard von Weizsäcker', 'Menschlichkeit ist unteilbar.', 'Ethik,Menschlichkeit,Gesellschaft'),
('Roman Herzog', 'Innovation entscheidet über unsere Zukunft.', 'Zukunft,Innovation,Fortschritt'),
('Alfred Dregger', 'Freiheit statt Sozialismus.', 'Politik,Freiheit,Kritik'),

-- LIBERTARISMUS & ÖKONOMIE (ERWEITERT)
('Murray Rothbard', 'Jeder Mensch hat das absolute Eigentum an seinem eigenen Körper.', 'Selbsteigentum,Recht,Freiheit'),
('Murray Rothbard', 'Bürokraten produzieren nichts, sie konsumieren nur den Fleiß anderer.', 'Staat,Bürokratie,Arbeit'),
('Murray Rothbard', 'Anarchie bedeutet nicht Chaos, sondern Ordnung ohne Herrscher.', 'Anarchie,Ordnung,Freiheit'),
('Hans-Hermann Hoppe', 'Privatrechtsgesellschaft ist die einzige rationale Alternative zum Staat.', 'Recht,Staat,Privat'),
('Hans-Hermann Hoppe', 'Ein Staat kann keinen Schutz bieten, da er selbst der größte Aggressor ist.', 'Staat,Sicherheit,Kritik'),
('Hans-Hermann Hoppe', 'Politik ist der Versuch, auf Kosten anderer zu leben.', 'Politik,Staat,Geld'),
('Ayn Rand', 'Ein schöpferischer Mensch ist motiviert durch den Wunsch zu erreichen, nicht durch den Wunsch, andere zu besiegen.', 'Erfolg,Motivation,Schöpfung'),
('Ayn Rand', 'Die Frage ist nicht, wer mich lässt, sondern wer mich stoppt.', 'Wille,Freiheit,Handeln'),
('Milton Friedman', 'Die größte Gefahr für die Freiheit ist die Konzentration von Macht.', 'Freiheit,Macht,Gefahr'),
('Milton Friedman', 'Der freie Markt ermöglicht es Menschen, zusammenzuarbeiten, ohne sich lieben zu müssen.', 'Markt,Gesellschaft,Zusammenarbeit'),
('Roland Baader', 'Wer den Staat füttert, zieht sich sein eigenes Monster heran.', 'Staat,Gefahr,Geld'),
('Roland Baader', 'Euro-Papiergeld ist Betrug am Sparer.', 'Geld,Inflation,Kritik'),
('Frédéric Bastiat', 'Was man sieht und was man nicht sieht.', 'Wirtschaft,Logik,Wahrnehmung'),
('Frédéric Bastiat', 'Plünderung ist einfacher als Arbeit.', 'Staat,Arbeit,Ethik'),
('Robert Nozick', 'Gerechtigkeit in der Aneignung, Gerechtigkeit in der Übertragung.', 'Recht,Eigentum,Gerechtigkeit'),
('Nassim Nicholas Taleb', 'Antifragilität ist jenseits von Resilienz oder Robustheit. Das Belastbare widersteht Schocks, das Antifragile wird besser.', 'Resilienz,Wissenschaft,Erfolg'),
('Nassim Nicholas Taleb', 'Das größte Risiko ist das, das man nicht sieht.', 'Risiko,Logik,Wahrheit');


-- ERGÄNZUNGS-BLOCK D: Aufklärung, Psychologie & Moderne Spiritualität (Vollzug)
INSERT INTO `sayings` (`author`, `content`, `tags`) VALUES
-- AUFKLÄRUNG (ERWEITERT)
('Immanuel Kant', 'Aufklärung ist der Ausgang des Menschen aus seiner selbstverschuldeten Unmündigkeit.', 'Aufklärung,Vernunft,Freiheit'),
('Immanuel Kant', 'Gedanken ohne Inhalt sind leer, Anschauungen ohne Begriffe sind blind.', 'Verstand,Philosophie'),
('John Locke', 'Niemand kann einem anderen mehr Macht geben, als er selbst hat.', 'Macht,Recht,Staat'),
('John Locke', 'Die Vernunft muss unser letzter Richter und Führer in allem sein.', 'Vernunft,Wahrheit'),
('Jean-Jacques Rousseau', 'Der Mensch ist frei geboren, und überall liegt er in Ketten.', 'Freiheit,Gesellschaft,Staat'),
('Jean-Jacques Rousseau', 'Zurück zur Natur!', 'Natur,Leben,Philosophie'),
('Jean-Jacques Rousseau', 'Geld ist ein guter Diener, aber ein schlechter Herr.', 'Geld,Macht'),
('Adam Smith', 'Der Konsum ist der einzige Zweck und das Ziel aller Produktion.', 'Wirtschaft,Konsum,Markt'),
('David Hume', 'Schönheit in den Dingen existiert im Geiste dessen, der sie betrachtet.', 'Ästhetik,Wahrnehmung,Geist'),
('David Hume', 'Die Wahrheit entspringt aus dem Streit unter Freunden.', 'Wahrheit,Diskurs'),

-- MODERNE PSYCHOLOGIE & EXISTENZIALISMUS
('Viktor Frankl', 'Sinn kann man nicht geben, Sinn muss man finden.', 'Sinn,Leben,Psychologie'),
('Carl Gustav Jung', 'Wahrheit ist das, was wirkt.', 'Wahrheit,Pragmatismus'),
('C.G. Jung', 'Die Begegnung zweier Persönlichkeiten ist wie der Kontakt zweier chemischer Substanzen: wenn es eine Reaktion gibt, werden beide transformiert.', 'Beziehung,Wandel'),
('Jordan Peterson', 'Disziplin ist die Grundlage der Freiheit.', 'Disziplin,Freiheit'),
('Albert Camus', 'Man muss sich Sisyphos als einen glücklichen Menschen vorstellen.', 'Glück,Absurdität,Sinn'),
('Albert Camus', 'Die wahre Großzügigkeit gegenüber der Zukunft besteht darin, alles der Gegenwart zu geben.', 'Zukunft,Gegenwart,Handeln'),

-- SPIRITUALITÄT & GEGENWART
('Eckhart Tolle', 'Vergangenheit und Zukunft sind nur Gedankenformen, mentale Abstraktionen.', 'Zeit,Geist,Gegenwart'),
('Eckhart Tolle', 'Frieden findest du nicht, indem du deine Lebensumstände neu ordnest, sondern indem du erkennst, wer du im Tiefsten bist.', 'Frieden,Selbsterkenntnis'),
('Dalai Lama', 'Begegne der Veränderung mit offenen Armen, aber verliere dabei deine Werte nicht aus den Augen.', 'Wandel,Werte,Ethik'),
('Dalai Lama', 'Mitgefühl ist das Fundament für Weltfrieden.', 'Frieden,Mitgefühl,Gesellschaft'),
('Søren Kierkegaard', 'Wagen ist Angst verlieren, nicht wagen ist sich selbst verlieren.', 'Mut,Angst,Identität'),
('Bertrand Russell', 'Die ganze Philosophie ist nur ein Kommentar zu Platon.', 'Philosophie,Wissen'),
('Nassim Taleb', 'Wer kein Risiko eingeht, hat keine Meinung.', 'Mut,Risiko,Integrität');

INSERT INTO sayings (author, content, tags) VALUES
-- 1. MARK AUREL (Römischer Kaiser & Philosoph)
('Mark Aurel', 'Das Glück deines Lebens hängt von der Beschaffenheit deiner Gedanken ab.', 'Geist, Glück, Psychologie'),
('Mark Aurel', 'Die beste Art, sich an jemandem zu rächen, ist, es ihm nicht gleichzutun.', 'Charakter, Ethik, Gerechtigkeit'),
('Mark Aurel', 'Du hast Macht über deinen Verstand – nicht über äußere Ereignisse. Erkenne dies, und du wirst Kraft finden.', 'Geist, Resilienz, Fokus'),
('Mark Aurel', 'Alles, was wir hören, ist eine Meinung, kein Faktum. Alles, was wir sehen, ist eine Perspektive, nicht die Wahrheit.', 'Geist, Wahrnehmung, Wahrheit'),
('Mark Aurel', 'Verschwende keine Zeit mehr damit, darüber zu streiten, was ein guter Mann sein sollte. Sei einer.', 'Charakter, Handeln, Ethik'),

-- 2. SENECA (Staatsmann & Dramatiker)
('Seneca', 'Nicht weil es schwer ist, wagen wir es nicht, sondern weil wir es nicht wagen, ist es schwer.', 'Mut, Erfolg, Handeln'),
('Seneca', 'Es ist nicht zu wenig Zeit, die wir haben, sondern es ist zu viel Zeit, die wir nicht nutzen.', 'Zeit, Fokus, Leben'),
('Seneca', 'Wer den Hafen nicht kennt, in den er segeln will, für den ist kein Wind ein günstiger.', 'Erfolg, Strategie, Fokus'),
('Seneca', 'Wir leiden häufiger in unserer Vorstellung als in der Wirklichkeit.', 'Geist, Angst, Psychologie'),
('Seneca', 'Glück ist das, was passiert, wenn Vorbereitung auf Gelegenheit trifft.', 'Erfolg, Vorbereitung, Glück'),

-- 3. EPIKTET (Ehemaliger Sklave & Lehrer)
('Epiktet', 'Es sind nicht die Dinge selbst, die uns beunruhigen, sondern die Vorstellungen von den Dingen.', 'Geist, Psychologie, Wahrnehmung'),
('Epiktet', 'Kein Mensch ist frei, der nicht Herr über sich selbst ist.', 'Freiheit, Disziplin, Charakter'),
('Epiktet', 'Wir haben zwei Ohren und einen Mund, damit wir doppelt so viel zuhören wie wir sprechen.', 'Weisheit, Kommunikation, Lernen'),
('Epiktet', 'Wähle nicht, dass die Dinge so geschehen, wie du willst, sondern wolle, dass sie so geschehen, wie sie geschehen.', 'Akzeptanz, Schicksal, Geist'),
('Epiktet', 'Nur der Gebildete ist frei.', 'Freiheit, Bildung, Geist'),

-- 4. ZENON VON KITION (Gründer der Stoa)
('Zenon von Kition', 'Das Ziel des Lebens ist es, im Einklang mit der Natur zu leben.', 'Natur, Leben, Ethik'),
('Zenon von Kition', 'Das Wohlergehen wird durch kleine Schritte erreicht, ist aber kein kleines Ding.', 'Erfolg, Geduld, Fortschritt'),
('Zenon von Kition', 'Nichts ist feindseliger für das Wissen als Selbsttäuschung.', 'Wahrheit, Geist, Ego'),
('Zenon von Kition', 'Ein Freund ist ein zweites Ich.', 'Freundschaft, Ethik'),
('Zenon von Kition', 'Die Vernunft ist die Herrscherin über alles.', 'Vernunft, Geist'),

-- 5. CHRYSIPPOS VON SOLOI (Der "zweite Gründer")
('Chrysippos', 'Wer rennt, sollte sich bemühen zu gewinnen, aber er darf seinem Konkurrenten kein Bein stellen.', 'Wettbewerb, Ethik, Gerechtigkeit'),
('Chrysippos', 'Das Universum ist ein einziges lebendiges Wesen, das von Vernunft durchdrungen ist.', 'Natur, Kosmos, Vernunft'),
('Chrysippos', 'Wenn ich den Leuten gefolgt wäre, wäre ich kein Philosoph geworden.', 'Individualismus, Freiheit, Geist'),
('Chrysippos', 'Laster ist ein schlechter Fluss des Lebens.', 'Ethik, Charakter'),
('Chrysippos', 'Der Weise hat keine Bedürfnisse, aber er braucht viele Dinge.', 'Genügsamkeit, Weisheit'),

-- 6. MUSONIUS RUFUS (Lehrer des Epiktet)
('Musonius Rufus', 'Wenn du etwas Gutes mit Mühe tust, vergeht die Mühe, aber das Gute bleibt.', 'Handeln, Tugend, Ethik'),
('Musonius Rufus', 'Nur wer philosophiert, kann wirklich glücklich sein.', 'Geist, Glück, Bildung'),
('Musonius Rufus', 'Wir sollten keine Angst vor dem Tod oder Schmerz haben, sondern vor der Angst selbst.', 'Mut, Resilienz, Psychologie'),
('Musonius Rufus', 'Die Tugend ist das einzige Gut des Menschen.', 'Charakter, Tugend, Ethik'),
('Musonius Rufus', 'Wahre Freiheit besteht darin, das zu tun, was man tun sollte.', 'Freiheit, Pflicht, Disziplin'),

-- 7. CATO DER JÜNGERE (Symbol stoischer Standhaftigkeit)
('Cato der Jüngere', 'Ich fange erst an zu sprechen, wenn ich sicher bin, dass ich nichts sage, was besser ungesagt bliebe.', 'Kommunikation, Selbstbeherrschung'),
('Cato der Jüngere', 'Ein weiser Mann lernt mehr von Narren als Narren von einem weisen Mann.', 'Lernen, Demut, Weisheit'),
('Cato der Jüngere', 'Tugend ist ihre eigene Belohnung.', 'Tugend, Charakter, Ethik'),
('Cato der Jüngere', 'Lieber bin ich tot als ein Sklave meiner Leidenschaften.', 'Freiheit, Disziplin, Charakter'),
('Cato der Jüngere', 'Es ist nicht wichtig, wie lange du lebst, sondern wie edel du lebst.', 'Leben, Ethik, Tod'),

-- 8. KLEANTHES (Nachfolger des Zenon)
('Kleanthes', 'Das Schicksal führt den Willigen und schleift den Unwilligen.', 'Schicksal, Akzeptanz, Geist'),
('Kleanthes', 'Unwissende Menschen unterscheiden sich von Tieren nur durch ihre Gestalt.', 'Bildung, Geist, Vernunft'),
('Kleanthes', 'Die Kunst zu leben gleicht eher dem Ringen als dem Tanzen.', 'Resilienz, Kampf, Leben'),
('Kleanthes', 'Wandle in Übereinstimmung mit deiner eigenen Natur.', 'Authentizität, Natur, Ethik'),
('Kleanthes', 'Reichtum ist ein Hindernis für die Philosophie.', 'Geld, Genügsamkeit, Weisheit'),

-- 9. PANAETIUS VON RHODOS (Gründer der mittleren Stoa)
('Panaetius', 'Jeder Mensch sollte seine eigenen Gaben pflegen und nicht versuchen, jemand anderes zu sein.', 'Authentizität, Charakter, Erfolg'),
('Panaetius', 'Die Pflicht ist die Grundlage des sozialen Zusammenhalts.', 'Staat, Gesellschaft, Pflicht'),
('Panaetius', 'Wir müssen lernen, unsere Begierden der Vernunft unterzuordnen.', 'Disziplin, Vernunft, Geist'),
('Panaetius', 'Großzügigkeit ohne Gerechtigkeit ist keine Tugend.', 'Gerechtigkeit, Ethik, Charakter'),
('Panaetius', 'Das Ziel ist die Vollkommenheit des täglichen Handelns.', 'Handeln, Perfektion, Ethik'),

-- 10. POSIDONIUS (Universalgelehrter der Stoa)
('Posidonius', 'Ein einzelner Tag eines Gelehrten ist mehr wert als das ganze Leben eines Unwissenden.', 'Bildung, Geist, Zeit'),
('Posidonius', 'Reichtum ist kein Gut, denn er macht die Menschen nicht besser.', 'Geld, Ethik, Charakter'),
('Posidonius', 'Die Leidenschaften sind Krankheiten der Seele.', 'Psychologie, Geist, Gesundheit'),
('Posidonius', 'Der Mensch ist geboren, um das Universum zu betrachten und nachzuahmen.', 'Natur, Kosmos, Weisheit'),
('Posidonius', 'Niemand ist frei, der ein Sklave seines Körpers ist.', 'Freiheit, Disziplin, Geist');

INSERT INTO sayings (author, content, tags) VALUES
-- 11. ARISTON VON CHIOS (Der Skeptiker unter den Stoikern)
('Ariston von Chios', 'Das höchste Gut ist die Gleichgültigkeit gegenüber Dingen, die zwischen Tugend und Laster stehen.', 'Ethik, Gleichmut, Charakter'),
('Ariston von Chios', 'Philosophische Dialektik ist wie ein Spinnennetz: kunstvoll, aber nutzlos.', 'Logik, Weisheit, Kritik'),
('Ariston von Chios', 'Es gibt nur eine Tugend: die Dinge so zu sehen, wie sie wirklich sind.', 'Wahrheit, Tugend, Geist'),
('Ariston von Chios', 'Gesetze sind für die Guten unnötig und halten die Bösen nicht auf.', 'Staat, Gerechtigkeit, Ethik'),
('Ariston von Chios', 'Wer sich zu sehr mit Details befasst, verliert den Blick für das Ganze.', 'Fokus, Weisheit'),

-- 12. DIOGENES VON BABYLON (Gesandter der Stoa in Rom)
('Diogenes von Babylon', 'Musik ist die beste Einstimmung der Seele auf die Tugend.', 'Geist, Tugend, Kunst'),
('Diogenes von Babylon', 'Ein guter Mensch ist ein Bürger der Welt.', 'Gesellschaft, Weltbürger, Ethik'),
('Diogenes von Babylon', 'Wahre Reichtümer sind nicht im Besitz, sondern im Gebrauch zu finden.', 'Geld, Genügsamkeit, Erfolg'),
('Diogenes von Babylon', 'Die Vernunft ist das Band, das Götter und Menschen vereint.', 'Vernunft, Geist, Natur'),
('Diogenes von Babylon', 'Man sollte so sprechen, dass man verstanden wird, nicht um zu glänzen.', 'Kommunikation, Bescheidenheit'),

-- 13. ANTIPATER VON TARSUS (Verteidiger der Moral)
('Antipater von Tarsus', 'Die Ehe ist eine Gemeinschaft des Lebens, begründet auf göttlichem und menschlichem Recht.', 'Gesellschaft, Ethik, Liebe'),
('Antipater von Tarsus', 'Ein weiser Mann wird immer versuchen, das Gemeinwohl über das eigene zu stellen.', 'Staat, Pflicht, Gerechtigkeit'),
('Antipater von Tarsus', 'Stille ist oft die mächtigste Antwort.', 'Selbstbeherrschung, Geist, Kommunikation'),
('Antipater von Tarsus', 'Der Wille zur Tugend ist bereits der halbe Weg zur Tugend.', 'Charakter, Handeln, Ethik'),
('Antipater von Tarsus', 'Wir sollten jeden Tag so leben, als ob wir vor einem Richter stünden.', 'Ethik, Disziplin, Charakter'),

-- 14. HEKATON VON RHODOS (Schüler des Panaetius)
('Hekaton', 'Ich werde dir ein Liebesmittel verraten ohne Tränke und Kräuter: Wenn du geliebt werden willst, dann liebe.', 'Liebe, Ethik, Geist'),
('Hekaton', 'Fragst du, was ich gewonnen habe? Ich habe angefangen, mir selbst ein Freund zu sein.', 'Psychologie, Selbstliebe, Geist'),
('Hekaton', 'Es ist ein Zeichen von Weisheit, nur das zu begehren, was man auch erreichen kann.', 'Erfolg, Genügsamkeit, Fokus'),
('Hekaton', 'Armut ist nur für den eine Last, der sich ihrer schämt.', 'Geld, Charakter, Resilienz'),
('Hekaton', 'Der Weise nutzt den Reichtum, aber er dient ihm nicht.', 'Geld, Freiheit, Disziplin'),

-- 15. ATHENODOROS KANANITES (Berater des Kaisers Augustus)
('Athenodoros', 'Lebe mit den Menschen so, als ob Gott dich sähe; sprich mit Gott so, als ob Menschen dich hörten.', 'Ethik, Spiritualität, Geist'),
('Athenodoros', 'Einsamkeit ist kein Exil, wenn man gute Gedanken als Gefährten hat.', 'Geist, Psychologie, Freiheit'),
('Athenodoros', 'Man erkennt den Charakter eines Mannes an seinem Verhalten in der Freizeit.', 'Charakter, Freizeit, Ethik'),
('Athenodoros', 'Nimm dir Zeit, bevor du zornig wirst; Zeit heilt den Zorn.', 'Selbstbeherrschung, Psychologie, Geist'),
('Athenodoros', 'Wahre Größe liegt darin, auch im Privaten so zu handeln wie in der Öffentlichkeit.', 'Integrität, Charakter, Ethik'),

-- 16. CORNUTUS (Lehrer der Dichter Persius und Lucan)
('Cornutus', 'Die Götter sind nur Symbole für die Kräfte der Natur.', 'Natur, Vernunft, Geist'),
('Cornutus', 'Philosophie ist die Reinigung der Seele von falschen Meinungen.', 'Bildung, Geist, Wahrheit'),
('Cornutus', 'Lerne zuerst zu gehorchen, bevor du versuchst zu herrschen.', 'Disziplin, Führung, Charakter'),
('Cornutus', 'Worte ohne Taten sind wie Schatten ohne Körper.', 'Handeln, Integrität, Ethik'),
('Cornutus', 'Wer die Natur versteht, verliert die Angst vor der Welt.', 'Natur, Wissen, Mut'),

-- 17. PERSIUS (Der stoische Satiriker)
('Persius', 'Suche die Antwort nicht außerhalb deiner selbst.', 'Geist, Psychologie, Wahrheit'),
('Persius', 'O ihr hohlen Seelen, die ihr euch um nichts als Gold sorgt!', 'Geld, Kritik, Ethik'),
('Persius', 'Freiheit ist die Macht, nach der Vernunft zu leben.', 'Freiheit, Vernunft, Geist'),
('Persius', 'Was nützt dir das Wissen, wenn du es nicht anwendest?', 'Lernen, Handeln, Erfolg'),
('Persius', 'Jeder trägt seinen eigenen Richter in sich.', 'Gewissen, Charakter, Ethik'),

-- 18. HIEROKLES (Der Stoiker der sozialen Kreise)
('Hierokles', 'Wir sollten jeden Menschen behandeln, als wäre er ein Teil unserer eigenen Familie.', 'Gesellschaft, Ethik, Gerechtigkeit'),
('Hierokles', 'Der Körper ist nur das Werkzeug der Seele.', 'Geist, Körper, Natur'),
('Hierokles', 'Die Vernunft befiehlt uns, nützlich für andere zu sein.', 'Pflicht, Gesellschaft, Vernunft'),
('Hierokles', 'Betrachte einen Fremden als hättest du ihn schon immer gekannt.', 'Menschlichkeit, Ethik, Staat'),
('Hierokles', 'Das eigene Selbst ist der innerste Kreis unserer Sorge.', 'Psychologie, Fokus, Geist'),

-- 19. SPHAERUS (Berater von Königen)
('Sphaerus', 'Ein König sollte zuerst über seine eigenen Leidenschaften herrschen.', 'Führung, Disziplin, Staat'),
('Sphaerus', 'Gleichheit ist die Basis einer stabilen Gemeinschaft.', 'Gerechtigkeit, Staat, Gesellschaft'),
('Sphaerus', 'Das Gesetz der Natur ist älter als jedes geschriebene Gesetz.', 'Natur, Recht, Staat'),
('Sphaerus', 'Mut besteht darin, die Wahrheit zu sagen, auch wenn sie gefährlich ist.', 'Mut, Wahrheit, Freiheit'),
('Sphaerus', 'Bildung ist das Fundament der Freiheit.', 'Bildung, Freiheit, Geist'),

-- 20. SERVIUS SULPICIUS RUFUS (Stoischer Jurist & Freund Ciceros)
('Servius Sulpicius', 'Nicht die Mauern machen eine Stadt, sondern die Gesetze und der Charakter ihrer Bürger.', 'Staat, Charakter, Gesellschaft'),
('Servius Sulpicius', 'Ein kurzer Schmerz ist besser als eine lange Reue.', 'Entscheidung, Erfolg, Geist'),
('Servius Sulpicius', 'In Zeiten des Unglücks zeigt sich das wahre Gesicht der Freundschaft.', 'Freundschaft, Resilienz, Charakter'),
('Servius Sulpicius', 'Gerechtigkeit ist der feste Wille, jedem sein Recht zuzuteilen.', 'Gerechtigkeit, Ethik, Staat'),
('Servius Sulpicius', 'Trost findet man nur in der Akzeptanz des Unvermeidlichen.', 'Resilienz, Akzeptanz, Schicksal');


INSERT INTO sayings (author, content, tags) VALUES
-- 1. LUDWIG VON MISES (Das Herz der Österreichischen Schule)
('Ludwig von Mises', 'Der Kapitalismus braucht keine Reklame und keine Propaganda; er zahlt sich durch seine Leistungen aus.', 'Geld, Freiheit, Erfolg'),
('Ludwig von Mises', 'Der Staat ist die einzige Instanz, die ein Papier nehmen, etwas Tinte darauf drucken und es in Geld verwandeln kann.', 'Geld, Staat, Inflation'),
('Ludwig von Mises', 'Freiheit ist immer Freiheit von staatlicher Einmischung.', 'Freiheit, Staat, Politik'),
('Ludwig von Mises', 'Wirtschaftliche Freiheit ist die Voraussetzung für jede andere Freiheit.', 'Freiheit, Erfolg, Geld'),
('Ludwig von Mises', 'Der Markt ist kein Ort, sondern ein Prozess.', 'Geld, Markt, Handeln'),

-- 2. FRIEDRICH AUGUST VON HAYEK (Nobelpreisträger & Analytiker des Wissens)
('F.A. von Hayek', 'Der Weg zur Knechtschaft beginnt mit dem Glauben, dass der Staat alles besser planen könne.', 'Staat, Freiheit, Politik'),
('F.A. von Hayek', 'Wettbewerb ist ein Entdeckungsverfahren.', 'Erfolg, Markt, Wissen'),
('F.A. von Hayek', 'Geld ist eines der größten Instrumente der Freiheit, die je erfunden wurden.', 'Geld, Freiheit, Gesellschaft'),
('F.A. von Hayek', 'Gerechtigkeit ist ein Verhalten von Individuen, keine Eigenschaft der Gesellschaft.', 'Gerechtigkeit, Ethik, Individualismus'),
('F.A. von Hayek', 'Die Forderung nach sozialer Gerechtigkeit ist die modernste Form des Aberglaubens.', 'Staat, Gerechtigkeit, Kritik'),

-- 3. MURRAY ROTHBARD (Anarchokapitalismus & Naturrecht)
('Murray Rothbard', 'Der Staat ist nichts anderes als eine kriminelle Organisation im großen Stil.', 'Staat, Freiheit, Recht'),
('Murray Rothbard', 'Besteuerung ist Raub, ganz gleich, wie viele Leute den Raub billigen.', 'Geld, Staat, Gerechtigkeit'),
('Murray Rothbard', 'Das Recht auf Selbsteigentum ist das fundamentale Axiom der Freiheit.', 'Freiheit, Individualismus, Ethik'),
('Murray Rothbard', 'Kapitalismus ist der vollendete Ausdruck der Freiheit im wirtschaftlichen Bereich.', 'Geld, Freiheit, Markt'),
('Murray Rothbard', 'Es ist kein Verbrechen, unwissend in Ökonomie zu sein; es ist aber unverantwortlich, eine Meinung zu äußern, während man unwissend bleibt.', 'Bildung, Wissen, Geld'),

-- 4. HANS-HERMANN HOPPE (Privatrechtsgesellschaft & Demokratiekritik)
('Hans-Hermann Hoppe', 'Demokratie ist der Gott, der keiner ist.', 'Staat, Politik, Kritik'),
('Hans-Hermann Hoppe', 'Es kann keine Freiheit ohne Privateigentum geben.', 'Freiheit, Geld, Recht'),
('Hans-Hermann Hoppe', 'Steuern sind nichts anderes als der Preis, den wir für die Erlaubnis zahlen, produktiv zu sein.', 'Geld, Staat, Erfolg'),
('Hans-Hermann Hoppe', 'Der Staat ist ein territorialer Monopolist des Zwangs.', 'Staat, Macht, Freiheit'),
('Hans-Hermann Hoppe', 'Zivilisation ist das Ergebnis von niedriger Zeitpräferenz.', 'Geist, Erfolg, Gesellschaft'),

-- 5. AYN RAND (Objektivismus & heroischer Individualismus)
('Ayn Rand', 'Man kann die Realität ignorieren, aber man kann nicht die Konsequenzen der ignorierten Realität ignorieren.', 'Geist, Wahrheit, Erfolg'),
('Ayn Rand', 'Die kleinste Minderheit auf Erden ist das Individuum.', 'Individualismus, Freiheit, Recht'),
('Ayn Rand', 'Geld ist das Barometer der Moral einer Gesellschaft.', 'Geld, Ethik, Gesellschaft'),
('Ayn Rand', 'Fragen Sie sich nicht, wer mich lassen wird, sondern wer mich stoppen will.', 'Erfolg, Mut, Freiheit'),
('Ayn Rand', 'Zivilisation ist der Fortschritt hin zu einer Privatsphäre.', 'Gesellschaft, Freiheit, Individualismus'),

-- 6. MILTON FRIEDMAN (Monetarismus & Freiheit des Marktes)
('Milton Friedman', 'Niemand gibt das Geld anderer Leute so sorgfältig aus wie sein eigenes.', 'Geld, Staat, Verantwortung'),
('Milton Friedman', 'Die Regierung ist nie die Lösung für ein Problem; sie ist das Problem.', 'Staat, Politik, Kritik'),
('Milton Friedman', 'Es gibt so etwas wie ein kostenloses Mittagessen nicht.', 'Erfolg, Geld, Wahrheit'),
('Milton Friedman', 'Eine Gesellschaft, die Gleichheit vor Freiheit stellt, wird am Ende weder das eine noch das andere haben.', 'Freiheit, Staat, Gerechtigkeit'),
('Milton Friedman', 'Die Inflation ist immer und überall ein monetäres Phänomen.', 'Geld, Inflation, Staat'),

-- 7. FREDERIC BASTIAT (Der Seher der "gebrochenen Fensterscheibe")
('Frederic Bastiat', 'Der Staat ist die große Fiktion, nach der jeder versucht, auf Kosten aller anderen zu leben.', 'Staat, Gerechtigkeit, Kritik'),
('Frederic Bastiat', 'Wenn Waren die Grenzen nicht überqueren, werden es Soldaten tun.', 'Frieden, Markt, Freiheit'),
('Frederic Bastiat', 'Die schlechten Ökonomen sehen nur das, was man sieht; die guten sehen auch das, was man nicht sieht.', 'Geld, Geist, Wahrheit'),
('Frederic Bastiat', 'Jeder Mensch hat ein natürliches Recht, seine Person, seine Freiheit und sein Eigentum zu verteidigen.', 'Freiheit, Recht, Ethik'),
('Frederic Bastiat', 'Gesetz ist organisierte Gerechtigkeit.', 'Staat, Recht, Gerechtigkeit'),

-- 8. ROLAND BAADER (Der deutsche Mahner der Freiheit)
('Roland Baader', 'Wer die Freiheit der Wirtschaft zerstört, bricht der Freiheit des Menschen das Rückgrat.', 'Freiheit, Geld, Politik'),
('Roland Baader', 'Geldsozialismus ist die Wurzel fast allen Übels der Gegenwart.', 'Geld, Staat, Kritik'),
('Roland Baader', 'Der Wohlfahrtsstaat ist der Vorhof zum Gefängnisstaat.', 'Staat, Freiheit, Politik'),
('Roland Baader', 'Demokratie ohne Privateigentum ist nur eine organisierte Plünderung.', 'Staat, Geld, Gerechtigkeit'),
('Roland Baader', 'Wahre Bildung ist die beste Versicherung gegen staatliche Manipulation.', 'Bildung, Freiheit, Geist'),

-- 9. NASSIM NICHOLAS TALEB (Antifragilität & Skin in the Game)
('Nassim Taleb', 'Freiheit ist nichts wert, wenn man kein Skin in the Game hat.', 'Freiheit, Verantwortung, Erfolg'),
('Nassim Taleb', 'Investiere in dich selbst. Du bist deine einzige sichere Währung.', 'Erfolg, Geld, Bildung'),
('Nassim Taleb', 'Ein Gelehrter ist jemand, der Dinge besser versteht als andere; ein Intellektueller ist jemand, der sie nur komplizierter macht.', 'Geist, Bildung, Wahrheit'),
('Nassim Taleb', 'Wer keine Risiken eingeht, lernt nichts.', 'Lernen, Erfolg, Mut'),
('Nassim Taleb', 'Die drei schädlichsten Süchte sind Heroin, Kohlenhydrate und ein monatliches Gehalt.', 'Freiheit, Erfolg, Psychologie'),

-- 10. HENRY HAZLITT (Wirtschaft in einer Lektion)
('Henry Hazlitt', 'Wirtschaftswissenschaften bestehen darin, die Folgen einer Handlung nicht nur kurzfristig, sondern langfristig zu betrachten.', 'Geld, Geist, Handeln'),
('Henry Hazlitt', 'Alles, was wir vom Staat erhalten, muss auf die eine oder andere Weise bezahlt werden.', 'Geld, Staat, Wahrheit'),
('Henry Hazlitt', 'Die einzige Art, die Armut zu bekämpfen, ist die Produktion von Reichtum zu ermöglichen.', 'Geld, Erfolg, Markt'),
('Henry Hazlitt', 'Inflation ist eine Steuer, die ohne Gesetz erhoben wird.', 'Geld, Inflation, Staat'),
('Henry Hazlitt', 'Der freie Markt ermöglicht es den Menschen, friedlich zusammenzuarbeiten.', 'Markt, Frieden, Freiheit');

INSERT INTO sayings (author, content, tags) VALUES
-- 11. LYSANDER SPOONER (Individualanarchist & Jurist)
('Lysander Spooner', 'Ein Mensch, der einen anderen gegen seinen Willen regiert, ist ein Tyrann.', 'Freiheit, Staat, Recht'),
('Lysander Spooner', 'Eigentum ist das Recht eines Menschen über seine eigene Person und seine Arbeit.', 'Individualismus, Geld, Recht'),
('Lysander Spooner', 'Die Verfassung hat entweder die Sklaverei erlaubt oder sie war unfähig, sie zu verhindern.', 'Staat, Recht, Kritik'),
('Lysander Spooner', 'Laster sind keine Verbrechen.', 'Ethik, Freiheit, Recht'),
('Lysander Spooner', 'Niemand ist verpflichtet, eine Regierung zu unterstützen, die er nicht selbst gewählt hat.', 'Staat, Freiheit, Politik'),

-- 12. H.L. MENCKEN (Der schärfste Kritiker der Demokratie)
('H.L. Mencken', 'Die ganze Kunst der Politik besteht darin, die Massen in Angst zu halten.', 'Staat, Politik, Macht'),
('H.L. Mencken', 'Demokratie ist die Theorie, dass das einfache Volk weiß, was es will, und es verdient, es fest zu bekommen.', 'Staat, Politik, Kritik'),
('H.L. Mencken', 'Ein Idealist ist jemand, der bemerkt, dass eine Rose besser riecht als ein Kohlkopf, und daraus schließt, dass sie auch eine bessere Suppe abgibt.', 'Geist, Wahrheit, Realität'),
('H.L. Mencken', 'Das Ziel der öffentlichen Erziehung ist nicht die Verbreitung von Wissen, sondern die Reduzierung von Menschen auf das Niveau von Sklaven.', 'Bildung, Staat, Freiheit'),
('H.L. Mencken', 'Gewissen ist die innere Stimme, die uns warnt, dass jemand zusehen könnte.', 'Ethik, Psychologie, Geist'),

-- 13. RON PAUL (Der "Godfather" der modernen Freiheitsbewegung)
('Ron Paul', 'Es ist kein Zufall, dass der Wohlfahrtsstaat und der Kriegsstaat Hand in Hand gehen.', 'Staat, Geld, Krieg'),
('Ron Paul', 'Wir brauchen keinen Goldstandard, um den Staat zu kontrollieren, sondern um die Bürger vor dem Staat zu schützen.', 'Geld, Freiheit, Staat'),
('Ron Paul', 'Freiheit bedeutet nicht die Abwesenheit von Regeln, sondern die Abwesenheit von Zwang.', 'Freiheit, Ethik, Gesellschaft'),
('Ron Paul', 'Echte Wohltätigkeit kann nur freiwillig sein.', 'Ethik, Staat, Gesellschaft'),
('Ron Paul', 'Beendet die Fed (Zentralbank) – sie ist die Wurzel der wirtschaftlichen Instabilität.', 'Geld, Inflation, Staat'),

-- 14. ALBERT JAY NOCK (Kritiker des Staates als "Eroberer")
('Albert Jay Nock', 'Der Staat beansprucht ein Monopol auf Verbrechen.', 'Staat, Macht, Recht'),
('Albert Jay Nock', 'Jede Ausweitung der Staatsmacht geht auf Kosten der Gesellschaftsmacht.', 'Staat, Freiheit, Gesellschaft'),
('Albert Jay Nock', 'Es gibt zwei Arten von Menschen: jene, die durch Arbeit leben, und jene, die durch Politik leben.', 'Erfolg, Geld, Staat'),
('Albert Jay Nock', 'Das schlimmste Unglück für ein Volk ist eine Regierung, die alles für es tun will.', 'Staat, Freiheit, Verantwortung'),
('Albert Jay Nock', 'Die Geschichte des Staates ist eine Geschichte von Gewalt und Raub.', 'Staat, Geschichte, Macht'),

-- 15. THOMAS SOWELL (Ökonom & scharfer Analytiker sozialer Mythen)
('Thomas Sowell', 'Es gibt keine Lösungen, nur Kompromisse.', 'Wahrheit, Strategie, Realität'),
('Thomas Sowell', 'Die erste Lektion der Ökonomie ist Knappheit; die erste Lektion der Politik ist das Ignorieren der ersten Lektion der Ökonomie.', 'Geld, Staat, Wahrheit'),
('Thomas Sowell', 'Was ist Rassismus anderes als eine Form des Kollektivismus?', 'Individualismus, Freiheit, Kritik'),
('Thomas Sowell', 'Gefährlich wird es, wenn Menschen, die keine Konsequenzen tragen müssen, Entscheidungen für andere treffen.', 'Staat, Verantwortung, Freiheit'),
('Thomas Sowell', 'Man muss nicht alles verstehen, um zu wissen, dass Freiheit funktioniert.', 'Freiheit, Erfolg, Markt'),

-- 16. DAVID FRIEDMAN (Anarchokapitalismus & ökonomische Logik)
('David Friedman', 'Privates Eigentum ist die Lösung für das Problem des Konflikts.', 'Geld, Recht, Frieden'),
('David Friedman', 'Ein Markt für Rechtsschutz ist effizienter als ein staatliches Monopol.', 'Recht, Staat, Markt'),
('David Friedman', 'Die Regierung ist eine Institution, die Dinge tut, die für Privatpersonen illegal wären.', 'Staat, Ethik, Recht'),
('David Friedman', 'Zentralplanung ist der Versuch, ein Puzzle zu lösen, dessen Teile sich ständig verändern.', 'Geld, Geist, Markt'),
('David Friedman', 'Freiheit ist nicht nur moralisch richtig, sie ist auch praktisch überlegen.', 'Freiheit, Erfolg, Ethik'),

-- 17. ROBERT NOZICK (Anarchie, Staat und Utopia)
('Robert Nozick', 'Besteuerung von Arbeitsverdienst ist gleichbedeutend mit Zwangsarbeit.', 'Geld, Freiheit, Staat'),
('Robert Nozick', 'Individuen haben Rechte, und es gibt Dinge, die keine Person oder Gruppe ihnen antun darf.', 'Freiheit, Individualismus, Recht'),
('Robert Nozick', 'Der Minimalstaat ist der weitestgehende Staat, der gerechtfertigt werden kann.', 'Staat, Freiheit, Gerechtigkeit'),
('Robert Nozick', 'Es gibt kein kollektives Wohl, das ein Opfer rechtfertigt.', 'Ethik, Individualismus, Staat'),
('Robert Nozick', 'Wahlfreiheit ist die Essenz der Würde.', 'Freiheit, Charakter, Ethik'),

-- 18. FRANK CHODOROV (Individualist & Gegner der Einkommensteuer)
('Frank Chodorov', 'Was der Staat gibt, hat er vorher jemand anderem weggenommen.', 'Geld, Staat, Gerechtigkeit'),
('Frank Chodorov', 'Die Einkommensteuer ist die Wurzel der Sklaverei des 20. Jahrhunderts.', 'Geld, Freiheit, Staat'),
('Frank Chodorov', 'Gesellschaft ist nur ein Wort für eine Gruppe von Individuen.', 'Individualismus, Gesellschaft, Wahrheit'),
('Frank Chodorov', 'Ohne Privateigentum gibt es keine Unabhängigkeit.', 'Geld, Freiheit, Erfolg'),
('Frank Chodorov', 'Der einzige Weg, den Staat zu begrenzen, ist ihm das Geld zu entziehen.', 'Geld, Staat, Macht'),

-- 19. WALTER BLOCK (Defending the Undefendable)
('Walter Block', 'Privatbesitz an Straßen würde Staus und Unfälle drastisch reduzieren.', 'Markt, Erfolg, Geld'),
('Walter Block', 'Jeder freiwillige Austausch ist zum Vorteil beider Seiten.', 'Markt, Erfolg, Ethik'),
('Walter Block', 'Der Staat ist ein Parasit auf der produktiven Klasse.', 'Staat, Geld, Erfolg'),
('Walter Block', 'Diskriminierung ist ein Teil der Freiheit der Assoziation.', 'Freiheit, Recht, Individualismus'),
('Walter Block', 'Es gibt kein Recht auf einen Job, nur das Recht, einen Vertrag anzubieten.', 'Markt, Freiheit, Arbeit'),

-- 20. ETIENNE DE LA BOÉTIE (Der Klassiker über die freiwillige Knechtschaft)
('Etienne de la Boétie', 'Seid entschlossen, nicht mehr zu dienen, und ihr seid frei.', 'Freiheit, Geist, Mut'),
('Etienne de la Boétie', 'Tyrannen sind nur groß, weil wir auf den Knien liegen.', 'Freiheit, Staat, Macht'),
('Etienne de la Boétie', 'Es ist unglaublich, wie schnell das Volk vergisst, dass es unterdrückt wird.', 'Psychologie, Staat, Geist'),
('Etienne de la Boétie', 'Freiheit ist das einzige Gut, das die Menschen nicht mehr begehren, sobald sie es verloren haben.', 'Freiheit, Psychologie, Ethik'),
('Etienne de la Boétie', 'Die Natur hat uns alle nach dem gleichen Muster geschaffen, damit wir uns als Brüder erkennen.', 'Individualismus, Ethik, Natur');

INSERT INTO sayings (author, content, tags) VALUES
-- 1. ROLAND BAADER (Der Analytiker des Geldsozialismus)
('Roland Baader', 'Papiergeld ist das Blut der Tyrannen.', 'Geld, Staat, Freiheit'),
('Roland Baader', 'Wer das Geld monopolisiert, monopolisiert die Freiheit.', 'Geld, Macht, Politik'),
('Roland Baader', 'Der Sozialismus ist nicht an seinen ökonomischen Fehlern gescheitert, sondern an seiner moralischen Verdorbenheit.', 'Ethik, Kritik, Politik'),
('Roland Baader', 'Ein Volk, das seine Freiheit für Sicherheit opfert, wird am Ende beides verlieren und den Spott dazu ernten.', 'Freiheit, Staat, Psychologie'),
('Roland Baader', 'Die Geschichte der Menschheit ist ein permanenter Kampf zwischen dem ökonomischen Mittel (Arbeit) und dem politischen Mittel (Raub).', 'Geld, Staat, Geschichte'),
('Roland Baader', 'Der Staat ist ein Gott, der keine anderen Götter neben sich duldet – am wenigsten das Individuum.', 'Staat, Individualismus, Kritik'),
('Roland Baader', 'Inflation ist die stillschweigende Enteignung der Fleißigen zugunsten der Verschwender.', 'Geld, Inflation, Gerechtigkeit'),
('Roland Baader', 'Zentralbanken sind die Planungsbehörden des monetären Chaos.', 'Geld, Staat, Markt'),
('Roland Baader', 'Wohlstand entsteht durch Produktion, nicht durch Bedrucken von Papier.', 'Geld, Erfolg, Wahrheit'),
('Roland Baader', 'Die Freiheit stirbt immer zentimeterweise, nie meterweise – deshalb merkt es kaum jemand.', 'Freiheit, Politik, Psychologie'),

-- 2. HANS-HERMANN HOPPE (Eigentum, Zivilisation & Demokratiekritik)
('Hans-Hermann Hoppe', 'Es kann keine Gerechtigkeit geben, wo es kein Eigentum gibt.', 'Gerechtigkeit, Recht, Geld'),
('Hans-Hermann Hoppe', 'Der Staat ist ein Agent der Zivilisationszerstörung.', 'Staat, Gesellschaft, Kritik'),
('Hans-Hermann Hoppe', 'Demokratie führt zwangsläufig zur Entwertung des Eigentums und zur Erhöhung der Zeitpräferenz.', 'Staat, Geld, Psychologie'),
('Hans-Hermann Hoppe', 'In einer Privatrechtsgesellschaft ist jeder für den Schutz seines Eigentums selbst verantwortlich.', 'Recht, Freiheit, Verantwortung'),
('Hans-Hermann Hoppe', 'Wer Steuern zahlt, finanziert seine eigene Unterdrückung.', 'Geld, Staat, Freiheit'),
('Hans-Hermann Hoppe', 'Der Staat ist ein Monopolist, der über Recht und Unrecht entscheidet – in eigener Sache.', 'Staat, Recht, Macht'),
('Hans-Hermann Hoppe', 'Echte Freiheit bedeutet das Recht, Nein zu sagen und in Ruhe gelassen zu werden.', 'Freiheit, Individualismus, Ethik'),
('Hans-Hermann Hoppe', 'Die Marktwirtschaft ist das einzige System, das Kooperation ohne Zwang ermöglicht.', 'Markt, Frieden, Freiheit'),
('Hans-Hermann Hoppe', 'Ein Monarch sieht das Land als sein Eigentum, ein demokratischer Politiker nur als Beute auf Zeit.', 'Staat, Politik, Geld'),
('Hans-Hermann Hoppe', 'Ohne Diskriminierung (Unterscheidung) gibt es keine Freiheit der Wahl.', 'Freiheit, Individualismus, Ethik'),

-- 3. MURRAY ROTHBARD (Anarchokapitalismus & Naturrecht)
('Murray Rothbard', 'Der Staat ist die einzige Organisation, die ihr Einkommen durch nackte Gewalt erzielt.', 'Staat, Geld, Macht'),
('Murray Rothbard', 'Krieg ist der Gesundheitszustand des Staates.', 'Staat, Krieg, Politik'),
('Murray Rothbard', 'Jeder Mensch ist der rechtmäßige Eigentümer seines eigenen Körpers.', 'Individualismus, Freiheit, Recht'),
('Murray Rothbard', 'Das staatliche Bildungssystem ist eine Maschinerie zur Erzeugung von Gehorsam.', 'Bildung, Staat, Geist'),
('Murray Rothbard', 'Es gibt keine Handlungen, die für den Staat moralisch sind, aber für den Einzelnen kriminell.', 'Ethik, Staat, Gerechtigkeit'),
('Murray Rothbard', 'Bürokratie ist das Gegenteil von Profitabilität.', 'Erfolg, Markt, Staat'),
('Murray Rothbard', 'Freiheit und Eigentum sind unzertrennlich.', 'Freiheit, Geld, Recht'),
('Murray Rothbard', 'Der freie Markt ist ein Netz von freiwilligen Tauschgeschäften zum gegenseitigen Nutzen.', 'Markt, Erfolg, Frieden'),
('Murray Rothbard', 'Wirtschaftliche Interventionen des Staates verschlimmern stets die Probleme, die sie zu lösen vorgeben.', 'Geld, Staat, Markt'),
('Murray Rothbard', 'Ein Anarchist ist jemand, der glaubt, dass wir ohne einen monopolitischen Gewaltherrscher besser dran sind.', 'Freiheit, Staat, Politik'),

-- 4. LUDWIG VON MISES (Menschliches Handeln & Logik)
('Ludwig von Mises', 'Wer die Wirtschaft kontrolliert, kontrolliert das Leben.', 'Geld, Macht, Freiheit'),
('Ludwig von Mises', 'Alle Versuche, die Gesetze des Marktes außer Kraft zu setzen, führen ins Chaos.', 'Markt, Geld, Wahrheit'),
('Ludwig von Mises', 'Der Verbraucher ist der Kapitän der Wirtschaft; er entscheidet durch seinen Kauf.', 'Erfolg, Markt, Freiheit'),
('Ludwig von Mises', 'Man kann den Sozialismus nicht mit ökonomischen Argumenten verbessern, man kann ihn nur abschaffen.', 'Geld, Politik, Kritik'),
('Ludwig von Mises', 'Menschliches Handeln ist zielgerichtetes Verhalten.', 'Handeln, Geist, Psychologie'),
('Ludwig von Mises', 'Ideen sind mächtiger als Armeen.', 'Geist, Macht, Geschichte'),
('Ludwig von Mises', 'Geld ist die Ware, die am leichtesten gegen andere Waren eingetauscht werden kann.', 'Geld, Markt, Wissen'),
('Ludwig von Mises', 'Es gibt keinen Mittelweg zwischen Kapitalismus und Sozialismus.', 'Markt, Politik, Wahrheit'),
('Ludwig von Mises', 'Der Staat ist dazu da, das Eigentum zu schützen, nicht um es zu verteilen.', 'Staat, Recht, Geld'),
('Ludwig von Mises', 'Die Freiheit des Individuums ist das einzige Ziel, das der Staat verfolgen sollte.', 'Freiheit, Staat, Individualismus');

INSERT INTO sayings (author, content, tags) VALUES
-- KRITISCHER RATIONALISMUS & WISSENSCHAFT
('Karl Popper', 'Unser Wissen ist ein kritisches Raten, ein Netz von Hypothesen, ein Gewebe von Vermutungen.', 'Geist, Wissen, Wahrheit'),
('Karl Popper', 'Wahre Unwissenheit ist nicht das Fehlen von Wissen, sondern die Weigerung, es zu erwerben.', 'Bildung, Geist, Wahrheit'),
('Karl Popper', 'Eine Theorie, die alles erklärt, erklärt gar nichts.', 'Geist, Wissenschaft, Logik'),
('Karl Popper', 'Wir wissen nicht, wir raten nur.', 'Geist, Wissen, Demut'),
('Karl Popper', 'Jede Lösung eines Problems wirft neue, ungelöste Probleme auf.', 'Erfolg, Fortschritt, Geist'),
('Karl Popper', 'Die Wissenschaft ist vielleicht die einzige menschliche Aktivität, in der Fehler systematisch kritisiert und korrigiert werden.', 'Geist, Lernen, Fortschritt'),
('Karl Popper', 'Ein Argument ist nur dann wissenschaftlich, wenn es widerlegbar ist.', 'Geist, Wissenschaft, Logik'),
('Karl Popper', 'Wer es nicht ertragen kann, dass seine Ideen kritisiert werden, sollte sich von der Wissenschaft fernhalten.', 'Charakter, Geist, Kritik'),
('Karl Popper', 'Es gibt keine letzte Wahrheit, nur eine Annäherung an die Wahrheit.', 'Wahrheit, Geist, Philosophie'),
('Karl Popper', 'Wir können aus unseren Fehlern lernen, wenn wir den Mut haben, sie zuzugeben.', 'Lernen, Charakter, Erfolg'),

-- DIE OFFENE GESELLSCHAFT & POLITIK
('Karl Popper', 'Die offene Gesellschaft ist eine, in der die Individuen mit persönlichen Entscheidungen konfrontiert werden.', 'Freiheit, Individualismus, Staat'),
('Karl Popper', 'Wir müssen für die Freiheit planen und nicht nur für die Sicherheit.', 'Freiheit, Staat, Politik'),
('Karl Popper', 'Wer die Freiheit aufgibt, um Sicherheit zu gewinnen, wird am Ende beides verlieren.', 'Freiheit, Staat, Sicherheit'),
('Karl Popper', 'Der Versuch, den Himmel auf Erden zu errichten, erzeugt stets die Hölle.', 'Staat, Politik, Kritik'),
('Karl Popper', 'Die Demokratie ist die einzige Regierungsform, die es erlaubt, die Regierung ohne Blutvergießen loszuwerden.', 'Staat, Politik, Freiheit'),
('Karl Popper', 'Uneingeschränkte Toleranz führt zum Verschwinden der Toleranz.', 'Staat, Gesellschaft, Ethik'),
('Karl Popper', 'Wir sollten nicht nach dem besten Herrscher suchen, sondern nach Institutionen, die schlechte Herrscher am meisten daran hindern, Schaden anzurichten.', 'Staat, Politik, Macht'),
('Karl Popper', 'Alles Reden von Gleichheit ist gefährlich, solange es nicht als Gleichheit vor dem Gesetz verstanden wird.', 'Gerechtigkeit, Staat, Freiheit'),
('Karl Popper', 'Freiheit ist wichtiger als Gleichheit.', 'Freiheit, Gerechtigkeit, Politik'),
('Karl Popper', 'Der Schutz der Minderheiten ist der Prüfstein für die Demokratie.', 'Staat, Gerechtigkeit, Recht'),

-- INDIVIDUALISMUS & ETHIK
('Karl Popper', 'Verantwortung ist immer individuell, niemals kollektiv.', 'Individualismus, Ethik, Verantwortung'),
('Karl Popper', 'Es gibt keinen Fortschritt in der Geschichte, es gibt nur Fortschritt durch unser Handeln.', 'Handeln, Geschichte, Erfolg'),
('Karl Popper', 'Handle nicht für ein abstraktes Gut, sondern für die Beseitigung eines konkreten Übels.', 'Ethik, Handeln, Politik'),
('Karl Popper', 'Optimismus ist Pflicht. Man muss sich auf die Dinge konzentrieren, die gemacht werden können.', 'Geist, Erfolg, Psychologie'),
('Karl Popper', 'Niemand ist weise genug, um ohne Kritik auszukommen.', 'Geist, Kritik, Demut'),
('Karl Popper', 'Ich kann mich irren, du kannst recht haben, und gemeinsam können wir der Wahrheit auf die Spur kommen.', 'Geist, Kommunikation, Wahrheit'),
('Karl Popper', 'Vernunft ist nicht eine Gabe, die man besitzt, sondern eine Methode, die man anwendet.', 'Geist, Vernunft, Logik'),
('Karl Popper', 'Glaube niemals, dass du die endgültige Antwort gefunden hast.', 'Geist, Wissen, Wahrheit'),
('Karl Popper', 'Wer die Vernunft aufgibt, öffnet der Gewalt Tür und Tor.', 'Vernunft, Frieden, Geist'),
('Karl Popper', 'Selbstbeherrschung ist die erste Bedingung der Freiheit.', 'Freiheit, Disziplin, Charakter'),

-- KRITIK AN TOTALITARISMUS & HISTORIZISMUS
('Karl Popper', 'Die Zukunft ist offen. Sie ist nicht vorherbestimmt.', 'Freiheit, Geist, Geschichte'),
('Karl Popper', 'Wer behauptet, den Lauf der Geschichte zu kennen, bereitet die Tyrannei vor.', 'Staat, Macht, Geschichte'),
('Karl Popper', 'Der Staat ist ein notwendiges Übel; seine Funktionen sollten auf das Minimum beschränkt bleiben.', 'Staat, Freiheit, Politik'),
('Karl Popper', 'Gegen Gewalt hilft nur Vernunft – oder eine noch größere Gewalt zur Verteidigung der Freiheit.', 'Freiheit, Mut, Macht'),
('Karl Popper', 'Institutionen sind wie Festungen: Sie müssen gut entworfen sein, aber sie brauchen auch gute Besatzungen.', 'Staat, Politik, Charakter'),
('Karl Popper', 'Utopien führen zwangsläufig zur Gewalt, da man die Menschen zur Glückseligkeit zwingen muss.', 'Staat, Politik, Kritik'),
('Karl Popper', 'Wir müssen kritisch gegenüber denen sein, die behaupten, die absolute Wahrheit zu besitzen.', 'Geist, Kritik, Politik'),
('Karl Popper', 'Die Geschichte hat keinen Sinn, aber wir können ihr einen Sinn geben.', 'Geist, Geschichte, Handeln'),
('Karl Popper', 'Bürokratie ist der Tod der Initiative.', 'Staat, Erfolg, Freiheit'),
('Karl Popper', 'Frieden ist nur möglich, wenn wir aufhören, andere mit Gewalt zu unseren Ideen bekehren zu wollen.', 'Frieden, Freiheit, Ethik');


INSERT INTO sayings (author, content, tags) VALUES
-- VOLUNTARISMUS & WILLE (Fokus auf Freiwilligkeit)
('Arthur Schopenhauer', 'Ganz er selbst sein darf jeder nur, solange er allein ist; wer also nicht die Einsamkeit liebt, der liebt auch nicht die Freiheit.', 'Individualismus, Freiheit, Geist'),
('Arthur Schopenhauer', 'Der Wille ist das Herrschende, der Intellekt das Dienende.', 'Geist, Vernunft, Psychologie'),
('Heinrich Pestalozzi', 'Der Mensch ist durch seinen Willen frei, aber auch durch seinen Willen Sklave.', 'Freiheit, Ethik, Geist'),
('Jean-Paul Sartre', 'Der Mensch ist dazu verurteilt, frei zu sein.', 'Freiheit, Verantwortung, Individualismus'),
('Jean-Paul Sartre', 'Freiheit ist das, was du mit dem tust, was man dir angetan hat.', 'Freiheit, Resilienz, Geist'),
('Frank Karsten', 'Voluntarismus bedeutet, dass Freiwilligkeit und persönliche Verantwortung Prinzipien jedes individuellen Handelns sind.', 'Freiheit, Verantwortung, Ethik'),
('Heinrich von Kleist', 'Die erste Handlung der Selbstständigkeit eines Menschen ist der Entwurf eines Lebensplans.', 'Erfolg, Individualismus, Handeln'),
('Albert Schweitzer', 'Das Geheimnis meines Erfolgs liegt darin, dass ich nie die Freiheit meines Willens aufgegeben habe.', 'Erfolg, Freiheit, Mut'),
('Erich Fromm', 'Die Fähigkeit, Nein zu sagen, ist der erste Schritt zur Freiheit.', 'Freiheit, Mut, Individualismus'),
('Ralph Waldo Emerson', 'Nichts ist endlich heilig außer der Integrität des eigenen Geistes.', 'Individualismus, Geist, Ethik'),

-- INDIVIDUALISMUS (Das Ich gegen das Kollektiv)
('Max Stirner', 'Mir geht nichts über Mich!', 'Individualismus, Freiheit, Geist'),
('Max Stirner', 'Meine Freiheit wird erst dann vollkommen, wenn sie meine Gewalt ist.', 'Individualismus, Macht, Freiheit'),
('Friedrich Nietzsche', 'Wahnsinn bei Individuen ist selten, aber in Gruppen, Nationen und Epochen die Regel.', 'Individualismus, Psychologie, Kritik'),
('Friedrich Nietzsche', 'Werden Sie, der Sie sind!', 'Individualismus, Charakter, Erfolg'),
('Simone de Beauvoir', 'Das Glück besteht darin, zu leben wie alle Welt und doch wie kein anderer zu sein.', 'Individualismus, Glück, Gesellschaft'),
('Oscar Wilde', 'Individualismus ist eine störende und zersetzende Kraft (für das System).', 'Individualismus, Freiheit, Kritik'),
('Henry David Thoreau', 'Wenn ein Mensch nicht Schritt hält mit seinen Gefährten, dann vielleicht deshalb, weil er einen anderen Trommler hört.', 'Individualismus, Freiheit, Charakter'),
('Mark Twain', 'Wann immer Sie sich auf der Seite der Mehrheit befinden, ist es Zeit, innezuhalten und nachzudenken.', 'Individualismus, Geist, Kritik'),
('Albert Einstein', 'Alles, was wirklich groß und inspirierend ist, wurde von Individuen geschaffen, die in Freiheit arbeiten konnten.', 'Individualismus, Freiheit, Erfolg'),
('Thomas Jefferson', 'Wir halten diese Wahrheiten für selbstverständlich: dass alle Menschen gleich geschaffen sind und unveräußerliche Rechte haben.', 'Freiheit, Recht, Individualismus'),

-- VERNUNFT & VERSTAND (Basis des Handelns)
('Immanuel Kant', 'Sapere aude! Habe Mut, dich deines eigenen Verstandes zu bedienen!', 'Vernunft, Geist, Bildung'),
('Immanuel Kant', 'Handle so, dass die Maxime deines Willens jederzeit als Prinzip einer allgemeinen Gesetzgebung gelten könnte.', 'Ethik, Vernunft, Gerechtigkeit'),
('Immanuel Kant', 'Aufklärung ist der Ausgang des Menschen aus seiner selbstverschuldeten Unmündigkeit.', 'Geist, Bildung, Freiheit'),
('René Descartes', 'Ich denke, also bin ich.', 'Geist, Wahrheit, Vernunft'),
('Voltaire', 'Wer dich dazu bringen kann, Absurditäten zu glauben, kann dich auch dazu bringen, Grausamkeiten zu begehen.', 'Geist, Vernunft, Ethik'),
('Baruch de Spinoza', 'Der freie Mensch lebt nach dem Diktat der Vernunft.', 'Vernunft, Freiheit, Geist'),
('Gottfried Wilhelm Leibniz', 'Ohne Vernunft gibt es keine Freiheit.', 'Vernunft, Freiheit, Logik'),
('David Hume', 'Die Vernunft ist die Sklavin der Leidenschaften.', 'Geist, Psychologie, Vernunft'),
('Thomas Paine', 'Mein eigener Geist ist meine eigene Kirche.', 'Individualismus, Freiheit, Geist'),
('Benjamin Franklin', 'Wer die Freiheit aufgibt, um Sicherheit zu gewinnen, wird am Ende beides verlieren.', 'Freiheit, Staat, Sicherheit'),

-- FREIHEIT & SELBSTBESTIMMUNG
('Johann Wolfgang von Goethe', 'Nur der verdient sich Freiheit wie das Leben, der täglich sie erobern muss.', 'Freiheit, Erfolg, Charakter'),
('Friedrich Schiller', 'Die Freiheit des Geistes ist die einzige Freiheit, die man nicht rauben kann.', 'Freiheit, Geist, Resilienz'),
('Abraham Lincoln', 'Wer anderen die Freiheit verweigert, verdient sie nicht für sich selbst.', 'Freiheit, Gerechtigkeit, Ethik'),
('Nelson Mandela', 'Frei zu sein bedeutet nicht nur, seine Ketten abzuwerfen, sondern so zu leben, dass man die Freiheit anderer respektiert.', 'Freiheit, Ethik, Gesellschaft'),
('Martin Luther King Jr.', 'Freiheit wird niemals freiwillig vom Unterdrücker gewährt; sie muss von den Unterdrückten eingefordert werden.', 'Freiheit, Mut, Gerechtigkeit'),
('Rose Wilder Lane', 'Freiheit ist ein innerer Zustand. Der Sklave kann im Geiste frei sein.', 'Freiheit, Geist, Resilienz'),
('George Orwell', 'Freiheit ist das Recht, den Leuten das zu sagen, was sie nicht hören wollen.', 'Freiheit, Wahrheit, Kritik'),
('Alexander von Humboldt', 'Die gefährlichste Weltanschauung ist die Weltanschauung derer, die die Welt nie angeschaut haben.', 'Geist, Bildung, Freiheit'),
('John Locke', 'Wo kein Gesetz ist, da ist keine Freiheit.', 'Staat, Freiheit, Recht'),
('Thomas Hobbes', 'Freiheit ist die Abwesenheit von Widerstand.', 'Freiheit, Natur, Logik');
